package com.ruoyi.ai.agent;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import junit.framework.TestCase;
import static com.ruoyi.ai.agent.AgentJson.*;

/** Pure failure-first B4 contract tests. No database setup, SQL or mock persistence. */
public class B4ManifestTest extends TestCase {
    private ObjectNode snapshot(){return (ObjectNode)parse("{\"sheets\":{\"s\":{\"id\":\"s\",\"name\":\"Orders\",\"rowCount\":20,\"columnCount\":10,\"cellData\":{\"0\":{\"0\":{\"v\":\"keep\",\"t\":1}},\"1\":{\"1\":{\"v\":0,\"t\":2,\"s\":{\"bg\":{\"rgb\":\"#ff0000\"}}},\"2\":{\"v\":false,\"t\":3},\"3\":{\"v\":\"\",\"t\":1}}}}}}");}
    private ObjectNode action(String type){return obj().put("type",type).put("schemaVersion","1.0").put("sheetId","s").put("range","B2");}
    private ObjectNode manifest(ObjectNode s,ObjectNode a,String policy){return WriteManifest.create(s,arr().add(a),parse("[{\"sheetId\":\"s\",\"range\":\"B2:D3\"}]"),"s",policy,"confirmed".equals(policy));}
    private void reject(Runnable r){try{r.run();fail("Unsafe action accepted");}catch(IllegalArgumentException expected){assertNotNull(expected.getMessage());}}
    public void testScalarAliasPreservesZeroFalseAndEmptyString(){for(JsonNode v:parse("[0,false,\"\",\"text\"]")){ObjectNode a=action("setCellForCell");a.set("value",v);ObjectNode m=manifest(snapshot(),a,"confirmed");assertEquals(v,m.path("cells").get(0).path("value"));assertEquals("setCellForCell",m.path("actions").get(0).path("type").asText());assertEquals(snapshot().path("sheets").path("s").path("cellData").path("1").path("1").path("s"),WriteManifest.apply(snapshot(),m).path("sheets").path("s").path("cellData").path("1").path("1").path("s"));}}
    public void testAliasRejectsNullObjectsFormulaAndMultiCellRange(){for(JsonNode v:parse("[null,{},[],\"=1+1\"]")){ObjectNode a=action("setCellForCell");a.set("value",v);reject(()->manifest(snapshot(),a,"confirmed"));}reject(()->manifest(snapshot(),action("setCellForCell").put("range","B2:C2").put("value",1),"confirmed"));}
    public void testContentClearPreservesStyleAndOutsideCell(){ObjectNode s=snapshot(),m=manifest(s,action("clearRange").put("range","B2:D2").put("clearWhat","content"),"confirmed"),next=WriteManifest.apply(s,m);assertEquals(3,m.path("cells").size());assertEquals(s.path("sheets").path("s").path("cellData").path("0"),next.path("sheets").path("s").path("cellData").path("0"));JsonNode after=next.path("sheets").path("s").path("cellData").path("1").path("1");assertTrue(after.path("v").isMissingNode()||after.path("v").isNull());assertEquals(s.path("sheets").path("s").path("cellData").path("1").path("1").path("s"),after.path("s"));}
    public void testMissingClearModeIsCanonicalContent(){assertEquals("content",manifest(snapshot(),action("clearRange"),"confirmed").path("actions").get(0).path("clearWhat").asText());}
    public void testFormatAllAndMixedGroupsRejected(){for(String mode:new String[]{"format","all","unknown"}){ObjectNode a=action("clearRange").put("clearWhat",mode);reject(()->WriteManifest.classify(arr().add(action("setCell").put("value",1)).add(a)));reject(()->manifest(snapshot(),a,"confirmed"));}}
    public void testClearNeedsOverwriteForZeroFalseEmptyAndRichText(){for(String range:new String[]{"B2","C2","D2"})reject(()->manifest(snapshot(),action("clearRange").put("range",range),"empty-only"));ObjectNode s=snapshot();((ObjectNode)s.path("sheets").path("s").path("cellData").path("1").path("1")).set("p",parse("{\"body\":{\"dataStream\":\"rich\\r\\n\"}}"));reject(()->manifest(s,action("setCellForCell").put("value",false),"empty-only"));ObjectNode next=WriteManifest.apply(s,manifest(s,action("setCellForCell").put("value",false),"confirmed"));assertFalse(next.path("sheets").path("s").path("cellData").path("1").path("1").hasNonNull("p"));assertEquals(BooleanNode.FALSE,WriteManifest.semanticValue(next.path("sheets").path("s").path("cellData").path("1").path("1")));}
    public void testClearRejectsCustomMetadataAndHiddenRows(){ObjectNode s=snapshot();((ObjectNode)s.path("sheets").path("s").path("cellData").path("1").path("1")).set("custom",obj().put("keep",true));reject(()->manifest(s,action("clearRange"),"confirmed"));ObjectNode hidden=snapshot();((ObjectNode)hidden.path("sheets").path("s")).set("rowData",parse("{\"1\":{\"hd\":1}}"));reject(()->manifest(hidden,action("clearRange"),"confirmed"));}
    public void testV2MissingTargetAndOutOfScopeRejected(){reject(()->manifest(snapshot(),action("clearRange").put("schemaVersion","2.0"),"confirmed"));reject(()->manifest(snapshot(),action("setCellForCell").put("range","A1").put("value",1),"confirmed"));}
    private ObjectNode plan(ObjectNode a,String kind){ObjectNode w=obj().put("stepId","W").put("tool","apply_actions"),v=obj().put("stepId","V").put("tool","verify_result");w.set("dependsOn",arr());w.set("inputBindings",obj().put("overwrite","confirmed").set("actions",arr().add(a)));w.set("verificationRules",arr().add(obj().put("type","tool_success")));v.set("dependsOn",arr().add("W"));ObjectNode in=obj().put("sheetId","s").put("range","B2").put("kind",kind);in.set("write",obj().put("$step","W"));v.set("inputBindings",in);v.set("verificationRules",arr().add(obj().put("type","tool_success")));ObjectNode p=obj();p.set("steps",arr().add(w).add(v));p.set("acceptanceCriteria",arr().add(obj().put("type","step_succeeded").put("stepId","W")).add(obj().put("type","step_succeeded").put("stepId","V")));return p;}
    public void testAgentClearHasExactSavedEffectVerification(){ObjectNode p=plan(action("clearRange"),"matches_write");AgentPlan.validateForRun(p,snapshot(),parse("[{\"sheetId\":\"s\",\"range\":\"B2\"}]"),"s",true,true);reject(()->AgentPlan.validateForRun(plan(action("clearRange"),"non_empty"),snapshot(),parse("[{\"sheetId\":\"s\",\"range\":\"B2\"}]"),"s",true,true));}
    public void testWrongReceiptAndFalseVsNullAreNotEquivalent(){ObjectNode m=manifest(snapshot(),action("clearRange"),"confirmed"),c=obj().put("sheetId","s").put("row",1).put("column",1).put("formula","");c.set("value",NullNode.instance);WriteManifest.validateReceipt(m,arr().add(c));c.put("value",false);reject(()->WriteManifest.validateReceipt(m,arr().add(c)));}
}
